input.content:
# Gym Auto-Booker: Southbank S&C

## Target
- **Class:** 5:30pm Mobility every Monday
- **Gym:** Southbank Strength & Conditioning (https://app.southbank-sc.com)
- **Account:** andrew.mercer@gmail.com

## How it works

### API Details
- **Base URL:** `https://app.southbank-sc.com`
- **Auth:** `POST /login` with `{"email": "...", "password": "..."}` — sets httpOnly session cookies
- **GraphQL endpoint:** `POST /graphql` (cookie-authenticated)
- **Timezone:** Australia/Brisbane (UTC+10)

### Key Queries/Mutations

**Fetch schedule:**
```graphql
query Classes($from: DateTime!, $to: DateTime!) {
  classes(from: $from, to: $to) {
    id classType startsAt endsAt capacity coachName confirmedCount spotsLeft
  }
}
```

**Book a class:**
```graphql
mutation CreateReservation($classInstanceId: ID!) {
  createReservation(classInstanceId: $classInstanceId) {
    reservation { id status waitlistPosition }
    errorCode
  }
}
```

**Cancel a booking:**
```graphql
mutation CancelReservation($reservationId: ID!) {
  cancelReservation(reservationId: $reservationId) { reservationId success }
}
```

**My bookings:**
```graphql
query MyReservations {
  myReservations {
    id status waitlistPosition createdAt
    classInstance { id classType startsAt coachName }
  }
}
```

### Booking Window
- Classes become bookable exactly **7 days (168 hours)** before the class start time
- Monday 5:30pm AEST Mobility → bookable at **Monday 5:30pm AEST** the prior week
- The check is client-side: `new Date(startsAt).getTime() > Date.now() + 7*24*60*60*1000`
- But the server also enforces it (returns error if too early)

### Monday 5:30pm Mobility
- `startsAt` is always `YYYY-MM-DDT07:30:00+00:00` (07:30 UTC = 17:30 AEST)
- `classType` is `mobility`
- Coach varies week to week

## Automation
The booking is handled via OpenClaw heartbeat checks every Monday.
The agent logs into the gym site, finds the target class, and books it as soon as the window opens.

#!/usr/bin/env node
/**
 * Gym Auto-Booker: Monday 5:30pm Mobility @ Southbank S&C
 * 
 * Logs in, finds the next Monday's 5:30pm Mobility class,
 * waits for the booking window to open (if needed), then books it.
 * 
 * Usage: node book-mobility.mjs
 * 
 * Environment variables (optional overrides):
 *   GYM_EMAIL    - defaults to andrew.mercer@gmail.com
 *   GYM_PASSWORD - defaults to Kettlebell42!
 */

const BASE_URL = 'https://app.southbank-sc.com';
const EMAIL = process.env.GYM_EMAIL || 'andrew.mercer@gmail.com';
const PASSWORD = process.env.GYM_PASSWORD || 'Kettlebell42!';
const MAX_RETRY_MS = 5 * 60 * 1000; // retry for up to 5 minutes
const RETRY_INTERVAL_MS = 3000;      // every 3 seconds

function log(msg) {
  console.log(`[${new Date().toISOString()}] ${msg}`);
}

/** Extract Set-Cookie headers from a fetch response */
function extractCookies(response, existingCookies = '') {
  const newCookies = [];
  const existing = new Map();

  // Parse existing cookies
  if (existingCookies) {
    for (const pair of existingCookies.split('; ')) {
      const [k, ...v] = pair.split('=');
      if (k) existing.set(k.trim(), v.join('='));
    }
  }

  // Parse Set-Cookie headers
  const setCookieHeaders = response.headers.getSetCookie?.() || [];
  for (const header of setCookieHeaders) {
    const cookiePart = header.split(';')[0];
    const [k, ...v] = cookiePart.split('=');
    if (k) existing.set(k.trim(), v.join('='));
  }

  return Array.from(existing.entries()).map(([k, v]) => `${k}=${v}`).join('; ');
}

async function login() {
  log(`Logging in as ${EMAIL}...`);
  const res = await fetch(`${BASE_URL}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
    redirect: 'manual',
  });

  if (!res.ok && res.status !== 302) {
    throw new Error(`Login failed: HTTP ${res.status}`);
  }

  const cookies = extractCookies(res);
  if (!cookies) {
    throw new Error('Login succeeded but no cookies received');
  }

  log('Login successful.');
  return cookies;
}

async function fetchClasses(cookies, from, to) {
  const res = await fetch(`${BASE_URL}/graphql`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Cookie': cookies,
    },
    body: JSON.stringify({
      operationName: 'Classes',
      variables: { from: from.toISOString(), to: to.toISOString() },
      query: `query Classes($from: DateTime!, $to: DateTime!) {
        classes(from: $from, to: $to) {
          id classType startsAt endsAt capacity coachName confirmedCount spotsLeft
        }
      }`,
    }),
  });

  const data = await res.json();
  return data.data.classes;
}

async function bookClass(cookies, classInstanceId) {
  const res = await fetch(`${BASE_URL}/graphql`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Cookie': cookies,
    },
    body: JSON.stringify({
      operationName: 'CreateReservation',
      variables: { classInstanceId },
      query: `mutation CreateReservation($classInstanceId: ID!) {
        createReservation(classInstanceId: $classInstanceId) {
          reservation { id status waitlistPosition }
          errorCode
        }
      }`,
    }),
  });

  const data = await res.json();
  return data.data.createReservation;
}

function getNextMonday() {
  const now = new Date();
  const day = now.getUTCDay(); // 0=Sun, 1=Mon, ...
  let daysAhead = (8 - day) % 7; // days until next Monday
  if (daysAhead === 0) daysAhead = 7; // if today is Monday, get next Monday

  const nextMon = new Date(now);
  nextMon.setUTCDate(nextMon.getUTCDate() + daysAhead);
  return nextMon.toISOString().split('T')[0]; // YYYY-MM-DD
}

async function main() {
  log('=== Southbank S&C Auto-Booker ===');

  // Step 1: Login
  const cookies = await login();

  // Step 2: Find next Monday's 5:30pm Mobility
  const from = new Date();
  const to = new Date(Date.now() + 14 * 24 * 60 * 60 * 1000);

  const classes = await fetchClasses(cookies, from, to);

  // Find Monday mobility at 07:30 UTC (= 17:30 AEST)
  const nextMonday = getNextMonday();
  log(`Looking for Monday ${nextMonday} 5:30pm Mobility class...`);

  const target = classes.find(c =>
    c.classType === 'mobility' &&
    c.startsAt.startsWith(nextMonday) &&
    c.startsAt.includes('T07:30:00')
  );

  if (!target) {
    // Maybe it's already Monday and we want today's
    const today = new Date().toISOString().split('T')[0];
    const todayTarget = classes.find(c =>
      c.classType === 'mobility' &&
      c.startsAt.startsWith(today) &&
      c.startsAt.includes('T07:30:00')
    );

    if (!todayTarget) {
      log('ERROR: Could not find target Mobility class.');
      log(`Available mobility classes: ${JSON.stringify(classes.filter(c => c.classType === 'mobility'), null, 2)}`);
      process.exit(1);
    }

    log(`Found today's class: ${todayTarget.id} (${todayTarget.startsAt}, coach: ${todayTarget.coachName}, spots: ${todayTarget.spotsLeft}/${todayTarget.capacity})`);
    await attemptBooking(cookies, todayTarget);
    return;
  }

  log(`Found class: ${target.id} (${target.startsAt}, coach: ${target.coachName}, spots: ${target.spotsLeft}/${target.capacity})`);

  // Step 3: Book it (with retries if booking window hasn't opened yet)
  await attemptBooking(cookies, target);
}

async function attemptBooking(cookies, target) {
  const startTime = Date.now();
  let attempt = 0;

  while (Date.now() - startTime < MAX_RETRY_MS) {
    attempt++;
    log(`Booking attempt #${attempt} for class ${target.id}...`);

    try {
      const result = await bookClass(cookies, target.id);

      if (result.reservation) {
        const { status, waitlistPosition } = result.reservation;

        if (status === 'confirmed') {
          log(`✅ BOOKED! Monday 5:30pm Mobility - Confirmed! (ID: ${result.reservation.id})`);
          process.exit(0);
        }

        if (status === 'waitlisted') {
          log(`⏳ Waitlisted at position #${waitlistPosition} (ID: ${result.reservation.id})`);
          process.exit(0);
        }

        log(`Unexpected status: ${status}`);
      }

      if (result.errorCode) {
        if (result.errorCode === 'NOT_YET_BOOKABLE') {
          log(`Not yet bookable, retrying in ${RETRY_INTERVAL_MS / 1000}s...`);
          await new Promise(r => setTimeout(r, RETRY_INTERVAL_MS));
          continue;
        }

        if (result.errorCode === 'ALREADY_BOOKED') {
          log('✅ Already booked for this class!');
          process.exit(0);
        }

        log(`Error: ${result.errorCode}`);
        // For CLASS_FULL, the mutation should auto-waitlist, but retry once
        if (result.errorCode === 'CLASS_FULL' && attempt === 1) {
          await new Promise(r => setTimeout(r, 1000));
          continue;
        }

        process.exit(1);
      }
    } catch (err) {
      log(`Request error: ${err.message}`);
      await new Promise(r => setTimeout(r, RETRY_INTERVAL_MS));
    }
  }

  log(`❌ Failed to book after ${attempt} attempts over ${MAX_RETRY_MS / 1000}s.`);
  process.exit(1);
}

main().catch(err => {
  log(`Fatal error: ${err.message}`);
  process.exit(1);
});

