input.fn:
() => {
  // Check how far ahead we can query classes - try 4 weeks out
  const from = new Date();
  const to = new Date(Date.now() + 28 * 24 * 60 * 60 * 1000);
  return fetch('/graphql', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    credentials: 'include',
    body: JSON.stringify({
      operationName: 'Classes',
      variables: { from: from.toISOString(), to: to.toISOString() },
      query: 'query Classes($from: DateTime!, $to: DateTime!) { classes(from: $from, to: $to) { id classType startsAt coachName spotsLeft } }'
    })
  }).then(r => r.json()).then(d => {
    const classes = d.data.classes;
    // Just get the Monday mobility classes
    const monMobility = classes.filter(c => c.classType === 'mobility' && c.startsAt.includes('T07:30:00'));
    const lastDate = classes[classes.length - 1]?.startsAt;
    return JSON.stringify({ totalClasses: classes.length, mondayMobility: monMobility, lastClassDate: lastDate }, null, 2);
  });
}

() => {
  // Monday mobility classes to book (filtering by Monday = day 1)
  // Mon 24 Aug is already booked. Need to book Mon 31 Aug and Mon 7 Sep.
  // The 5:30pm mobility classes on Mondays have startsAt at 07:30 UTC
  // Mon 17 Aug: 1e372f75... - already full (0 spots)
  // Mon 24 Aug: db66cb91... - already booked
  // Mon 31 Aug: d042bdde-581d-56bf-91e1-7f803af4d78f
  // Mon 7 Sep:  da07eb68-a9c6-5e86-a450-75c2cb870f67

  const toBook = [
    { id: 'd042bdde-581d-56bf-91e1-7f803af4d78f', date: 'Mon 31 Aug' },
    { id: 'da07eb68-a9c6-5e86-a450-75c2cb870f67', date: 'Mon 7 Sep' }
  ];

  return Promise.all(toBook.map(async (cls) => {
    const res = await fetch('/graphql', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'include',
      body: JSON.stringify({
        operationName: 'CreateReservation',
        variables: { classInstanceId: cls.id },
        query: 'mutation CreateReservation($classInstanceId: ID!) { createReservation(classInstanceId: $classInstanceId) { reservation { id status waitlistPosition } errorCode } }'
      })
    });
    const data = await res.json();
    return { ...cls, result: data.data.createReservation };
  })).then(results => JSON.stringify(results, null, 2));
}

